insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('recovery-gap-scheduler', 'Recovery Gap Scheduler', 'worksheet'::resource_kind, 'A week grid for placing rest gaps between demanding commitments.', 'Use it to help a client build breathing room into a full week.', array['Adults', 'Teens']::text[], '20 minutes', 'Mark the demanding items on a week grid first, then place a recovery gap after each one, even ten minutes. Ask what the client does in a gap and whether it refills them. Expect some gaps to be swallowed; adjust the size, not the client.', '[{"id": "f0", "type": "textarea", "label": "The most demanding items this week:"}, {"id": "f1", "type": "textarea", "label": "Where I will place a recovery gap:"}, {"id": "f2", "type": "textarea", "label": "What I will do in the gap:"}, {"id": "f3", "type": "textarea", "label": "What happens if the gap gets used up:"}]'::jsonb, array['worksheet', 'planning', 'energy']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('calendar-color-coding-by-value', 'Calendar Color-Coding by Value', 'worksheet'::resource_kind, 'A calendar page where each block is colored by the value it serves.', 'Use it to help a client see which values their calendar honors.', array['Adults', 'Teens']::text[], 'Full session', 'Choose a color for each of three values and shade last week''s calendar. White space is information too. Let the client interpret the picture first and ask what one block they would recolor.', '[{"id": "f0", "type": "textarea", "label": "My three values and their colors:"}, {"id": "f1", "type": "textarea", "label": "The color that shows up most:"}, {"id": "f2", "type": "textarea", "label": "A color that barely appears:"}, {"id": "f3", "type": "textarea", "label": "One block I would change:"}]'::jsonb, array['worksheet', 'values', 'planning']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('ten-ten-ten-decision-timeline', 'Ten-Ten-Ten Decision Timeline', 'worksheet'::resource_kind, 'A sheet for imagining a choice ten minutes, ten months and ten years out.', 'Use it to help a client look at a decision across time.', array['Adults', 'Teens']::text[], '30 minutes', 'For each time frame the client writes how the choice might feel. Differences between frames are the useful part. Keep the decision with the client and avoid steering toward either answer.', '[{"id": "f0", "type": "textarea", "label": "The choice in front of me:"}, {"id": "f1", "type": "textarea", "label": "How it might feel in ten minutes:"}, {"id": "f2", "type": "textarea", "label": "How it might feel in ten months:"}, {"id": "f3", "type": "textarea", "label": "How it might feel in ten years:"}]'::jsonb, array['worksheet', 'decisions', 'timeline']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('who-gets-the-call-role-cards', 'Who Gets the Call Role Cards', 'worksheet'::resource_kind, 'Cards matching types of help, such as listening or practical aid, with people who offer them.', 'Use it to help a client match the right kind of help to the right person.', array['Adults', 'Teens']::text[], '25 minutes', 'Write kinds of help on cards, such as a ride, a listening ear or a laugh, and have the client place a name on each. Empty cards show where support is thin. Choose one empty card to work on together.', '[{"id": "f0", "type": "textarea", "label": "Someone I call to just listen:"}, {"id": "f1", "type": "textarea", "label": "Someone who helps with practical things:"}, {"id": "f2", "type": "textarea", "label": "A kind of help nobody covers yet:"}, {"id": "f3", "type": "textarea", "label": "One person I could ask this week:"}]'::jsonb, array['worksheet', 'support', 'connection']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('morning-and-evening-bookend-planner', 'Morning and Evening Bookend Planner', 'worksheet'::resource_kind, 'A short planner for choosing one anchor to start the day and one to end it.', 'Use it to build small predictable routines at either end of the day.', array['Adults', 'Teens']::text[], '20 minutes', 'Keep the anchors small enough to do on a bad day, such as a glass of water or turning off a screen. Check in next session about what got in the way instead of what was missed. Adjust the anchor, not the client''s effort.', '[{"id": "f0", "type": "textarea", "label": "One thing I will do to start my day:"}, {"id": "f1", "type": "textarea", "label": "One thing I will do to end my day:"}, {"id": "f2", "type": "textarea", "label": "What could get in the way:"}, {"id": "f3", "type": "textarea", "label": "How I will adjust if it does:"}]'::jsonb, array['worksheet', 'routine', 'sleep']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('thought-record-with-alternative-views', 'Thought Record With Alternative Views', 'cbt'::resource_kind, 'A thought record with a column for three other ways to view the same event.', 'Use it to help a client loosen a single automatic reading of an event.', array['Adults', 'Teens']::text[], '30 minutes', 'After the usual situation, thought and feeling columns, the client writes three alternative views, one of them a friend''s. Work one example live in session. Clients often rush to a positive spin; aim for a view that is plausible, not cheerful.', '[{"id": "f0", "type": "textarea", "label": "The situation:"}, {"id": "f1", "type": "textarea", "label": "My first thought and how strongly I believed it:"}, {"id": "f2", "type": "textarea", "label": "Three other ways to see it:"}, {"id": "f3", "type": "textarea", "label": "What I feel now and what I might do:"}]'::jsonb, array['CBT', 'thought record', 'cognitive restructuring']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('mini-prediction-test-cards', 'Mini Prediction Test Cards', 'cbt'::resource_kind, 'Index cards that each hold one small prediction, a test and the result.', 'Use it to run several quick tests of a belief across a week.', array['Adults', 'Teens']::text[], 'One week', 'Cards are small on purpose, so tests stay quick. The client fills the front before and the back after. Bring the stack to session and sort cards into predictions that held and ones that did not.', '[{"id": "f0", "type": "textarea", "label": "A prediction I want to test:"}, {"id": "f1", "type": "textarea", "label": "The quick test I will do:"}, {"id": "f2", "type": "textarea", "label": "What happened:"}, {"id": "f3", "type": "textarea", "label": "Which cards surprised me:"}]'::jsonb, array['CBT', 'predictions', 'experiment']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('cognitive-distortion-spotter-cards', 'Cognitive Distortion Spotter Cards', 'cbt'::resource_kind, 'A set of cards naming common thinking traps for sorting a client''s own thoughts.', 'Use it to give a client words for common thinking patterns.', array['Adults', 'Teens']::text[], '25 minutes', 'Write the client''s own recent thoughts on slips of paper and sort them under trap names such as mind reading or all-or-nothing. Naming a pattern is a first step, not the end; follow with a question about what else could be true.', '[{"id": "f0", "type": "textarea", "label": "A thought I had this week:"}, {"id": "f1", "type": "textarea", "label": "The thinking trap it most looks like:"}, {"id": "f2", "type": "textarea", "label": "What the trap leaves out:"}, {"id": "f3", "type": "textarea", "label": "A more balanced way to say it:"}]'::jsonb, array['CBT', 'thinking traps', 'sorting']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('activity-log-with-mastery-and-pleasure-ratings', 'Activity Log With Mastery and Pleasure Ratings', 'cbt'::resource_kind, 'An hourly log where each activity gets a mastery rating and a pleasure rating.', 'Use it to see which parts of the week lift or sap a client''s mood.', array['Adults', 'Teens']::text[], 'One week', 'Rate each from 0 to 10. Review the log for patterns by time of day and by activity type rather than for any single entry. Choose one higher-rated activity to schedule more of. Keep the log light so it does not become a chore.', '[{"id": "f0", "type": "textarea", "label": "Activities I did on my best day:"}, {"id": "f1", "type": "textarea", "label": "Activities I did on my hardest day:"}, {"id": "f2", "type": "textarea", "label": "Patterns I notice in my ratings:"}, {"id": "f3", "type": "textarea", "label": "One activity I want to schedule more:"}]'::jsonb, array['CBT', 'activity scheduling', 'mood']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('belief-origin-and-update-timeline', 'Belief Origin and Update Timeline', 'cbt'::resource_kind, 'A timeline for noting where a belief took shape and what has happened since.', 'Use it to help a client see a belief as learned and open to updating.', array['Adults']::text[], 'Full session', 'Stay in the middle years and recent events; the client need not revisit hard early memories in detail. Mark times when events did not fit the belief. Close by drafting a more flexible version in their words.', '[{"id": "f0", "type": "textarea", "label": "A belief I carry about myself:"}, {"id": "f1", "type": "textarea", "label": "A time I learned it, in a sentence:"}, {"id": "f2", "type": "textarea", "label": "Times since then that did not fit:"}, {"id": "f3", "type": "textarea", "label": "A more flexible version:"}]'::jsonb, array['CBT', 'core beliefs', 'timeline']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('unwelcome-guests-dinner-party-scene', 'Unwelcome Guests Dinner Party Scene', 'act'::resource_kind, 'A role-play where difficult thoughts arrive as guests at a party the client hosts.', 'Use it to practice welcoming thoughts without letting them run the evening.', array['Adults', 'Teens']::text[], '25 minutes', 'The client is the host and you play the guests, who are the client''s own thoughts. The host keeps serving the meal. Debrief on how the host stayed on task and what the host cared about.', '[{"id": "f0", "type": "textarea", "label": "The guests who show up most:"}, {"id": "f1", "type": "textarea", "label": "What they say when they arrive:"}, {"id": "f2", "type": "textarea", "label": "What I do as a host:"}, {"id": "f3", "type": "textarea", "label": "What I would like the evening to be about:"}]'::jsonb, array['ACT', 'defusion', 'metaphor']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('thought-labeling-sticky-note-practice', 'Thought Labeling Sticky-Note Practice', 'act'::resource_kind, 'A practice of writing each thought on a note and labeling it as only a thought.', 'Use it to help a client see thoughts as events, not facts.', array['Adults', 'Teens']::text[], '15 minutes', 'Write thoughts on sticky notes and add "I am having the thought that" to each. Stick them on a wall and look together. Ask what changed when they were out of the head and on the wall.', '[{"id": "f0", "type": "textarea", "label": "Thoughts I wrote down:"}, {"id": "f1", "type": "textarea", "label": "What changed when I added \"I am having the thought\":"}, {"id": "f2", "type": "textarea", "label": "The one that still pulls hardest:"}, {"id": "f3", "type": "textarea", "label": "What I want to do anyway:"}]'::jsonb, array['ACT', 'defusion', 'experiential']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('creative-hopelessness-inventory', 'Creative Hopelessness Inventory', 'act'::resource_kind, 'A list of what a client has tried to control a feeling and what it cost them.', 'Use it to examine the price of the strategies a client already uses.', array['Adults']::text[], '30 minutes', 'Let the client list every strategy, how well it worked short term, and what it cost long term. Do not argue; let the ledger speak. Close with openness about trying something different, not with a claim that their efforts were wrong.', '[{"id": "f0", "type": "textarea", "label": "Things I have tried to get rid of this feeling:"}, {"id": "f1", "type": "textarea", "label": "What each one gave me short term:"}, {"id": "f2", "type": "textarea", "label": "What each one has cost me over time:"}, {"id": "f3", "type": "textarea", "label": "What I might be willing to try instead:"}]'::jsonb, array['ACT', 'control', 'workability']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('committed-action-micro-step-ladder', 'Committed Action Micro-Step Ladder', 'act'::resource_kind, 'A ladder of five steps from tiny to bigger toward one chosen value.', 'Use it to turn a value into steps the client can take this week.', array['Adults', 'Teens']::text[], '20 minutes', 'Start the client at the lowest rung, one they could do in under five minutes. Name the obstacle and the willingness it will take. Check the ladder next session and move it, not the client, if a rung was too high.', '[{"id": "f0", "type": "textarea", "label": "The value I want to move toward:"}, {"id": "f1", "type": "textarea", "label": "Rung one, under five minutes:"}, {"id": "f2", "type": "textarea", "label": "A bigger rung I might reach:"}, {"id": "f3", "type": "textarea", "label": "What I am willing to feel to take the step:"}]'::jsonb, array['ACT', 'committed action', 'values']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('self-as-context-sky-and-weather-visual', 'Self-as-Context Sky and Weather Visual', 'act'::resource_kind, 'A sky and weather drawing to show the observing self as the sky that holds passing thoughts and feelings.', 'Use it to help a client notice a steady observer beneath changing experience.', array['Adults', 'Teens']::text[], '20 minutes', 'Have the client draw a sky and label clouds and storms with this week''s thoughts and feelings. Ask what has stayed the same behind all of it. Offer the metaphor lightly and drop it if it does not fit.', '[{"id": "f0", "type": "textarea", "label": "The weather in my sky this week:"}, {"id": "f1", "type": "textarea", "label": "The part of me that watched it happen:"}, {"id": "f2", "type": "textarea", "label": "What the sky stays the same through:"}, {"id": "f3", "type": "textarea", "label": "How I could remember this on a stormy day:"}]'::jsonb, array['ACT', 'self-as-context', 'metaphor']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('emotion-fits-the-facts-walkthrough', 'Emotion Fits-the-Facts Walkthrough', 'dbt'::resource_kind, 'A walkthrough that checks whether an emotion and its strength fit the facts.', 'Use it to help a client check an emotion against the situation.', array['Adults', 'Teens']::text[], '25 minutes', 'Walk through the facts of a recent event, what the client assumed, and whether the emotion fits in kind and strength. If it fits, problem-solve. If it does not, plan an action opposite to the urge.', '[{"id": "f0", "type": "textarea", "label": "What happened, just the facts:"}, {"id": "f1", "type": "textarea", "label": "What I assumed:"}, {"id": "f2", "type": "textarea", "label": "The emotion and how strong it was:"}, {"id": "f3", "type": "textarea", "label": "Whether it fit the facts, and what I will do:"}]'::jsonb, array['DBT', 'emotion regulation', 'check the facts']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('three-circles-overlap-drawing', 'Three Circles Overlap Drawing', 'dbt'::resource_kind, 'A drawing of emotion, reason and the overlap between them.', 'Use it to help a client see where wise mind sits.', array['Adults', 'Teens']::text[], '20 minutes', 'Draw two circles and the overlap. Write what emotion mind says on one side, reasonable mind on the other, and a wise statement in the center. Let the client color it. Keep it for the next hard moment.', '[{"id": "f0", "type": "textarea", "label": "What emotion mind says:"}, {"id": "f1", "type": "textarea", "label": "What reasonable mind says:"}, {"id": "f2", "type": "textarea", "label": "What fits in the center:"}, {"id": "f3", "type": "textarea", "label": "How I can find the center in the moment:"}]'::jsonb, array['DBT', 'wise mind', 'drawing']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('give-skill-rehearsal-script', 'GIVE Skill Rehearsal Script', 'dbt'::resource_kind, 'A script for rehearsing the gentle, interested, validating and easy-manner parts of GIVE.', 'Use it to practice keeping a relationship while asking for something.', array['Adults', 'Teens']::text[], '25 minutes', 'Role-play a real upcoming conversation, giving the client a turn as each person. Go through each letter in turn. Pay attention to tone and ask which part is hardest to keep up when the client is upset.', '[{"id": "f0", "type": "textarea", "label": "The person and what I want from them:"}, {"id": "f1", "type": "textarea", "label": "How I will be gentle:"}, {"id": "f2", "type": "textarea", "label": "How I will show interest and validate:"}, {"id": "f3", "type": "textarea", "label": "The easy manner I will bring:"}]'::jsonb, array['DBT', 'interpersonal effectiveness', 'GIVE']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('self-soothe-with-five-senses-kit-list', 'Self-Soothe With Five Senses Kit List', 'dbt'::resource_kind, 'A list for building a small kit that soothes through sight, sound, smell, taste and touch.', 'Use it to build a kit a client can reach for when distress rises.', array['Adults', 'Teens']::text[], '20 minutes', 'Help the client choose one item per sense that they actually like, not what they think they should. Try one in session. Keep the kit somewhere easy to reach, and name when to use it, not only that it exists.', '[{"id": "f0", "type": "textarea", "label": "Something to look at that calms me:"}, {"id": "f1", "type": "textarea", "label": "A sound that soothes me:"}, {"id": "f2", "type": "textarea", "label": "A smell or taste that I like:"}, {"id": "f3", "type": "textarea", "label": "Something to touch, and where I will keep my kit:"}]'::jsonb, array['DBT', 'distress tolerance', 'self-soothe']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('pros-and-cons-of-acting-on-urges', 'Pros and Cons of Acting on Urges', 'dbt'::resource_kind, 'A grid weighing the short-term and long-term pros and cons of acting on an urge versus tolerating it.', 'Use it to slow down an urge by looking at four outcomes.', array['Adults', 'Teens']::text[], '25 minutes', 'Fill it in when the client is calm, not in the middle of an urge, then keep it handy. Talk through all four boxes honestly, including the real short-term pull of acting. If self-harm is involved, complete it in session, not as homework.', '[{"id": "f0", "type": "textarea", "label": "The urge I am looking at:"}, {"id": "f1", "type": "textarea", "label": "Pros and cons of acting on it:"}, {"id": "f2", "type": "textarea", "label": "Pros and cons of getting through it without acting:"}, {"id": "f3", "type": "textarea", "label": "If things feel unsafe, I can call or text 988 or tell someone now:"}]'::jsonb, array['DBT', 'distress tolerance', 'urges']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('cool-down-break-agreement-for-two', 'Cool-Down Break Agreement for Two', 'couples'::resource_kind, 'A written agreement about how partners will pause a heated talk and return.', 'Use it to give partners a shared plan for taking a break.', array['Couples']::text[], '30 minutes', 'Agree on a signal, a time away of at least twenty minutes, and a time to return. Partner A and Partner B each say what they will do during the break. The partner who calls the break is the one who restarts the talk.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how I will signal a break:"}, {"id": "f1", "type": "textarea", "label": "Partner B: how I will signal a break:"}, {"id": "f2", "type": "textarea", "label": "What we each do during the break:"}, {"id": "f3", "type": "textarea", "label": "How we will come back:"}]'::jsonb, array['couples', 'breaks', 'communication']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('monthly-relationship-garden-review', 'Monthly Relationship Garden Review', 'couples'::resource_kind, 'A monthly review of what is growing, what needs water and what needs weeding.', 'Use it to help partners look at the relationship over a longer span.', array['Couples']::text[], '45 minutes', 'Set a monthly date. Partner A and Partner B each name what is growing, what needs attention and one small action. Keep complaints to one per partner and end with something warm.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what is growing in us:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what is growing in us:"}, {"id": "f2", "type": "textarea", "label": "What needs attention:"}, {"id": "f3", "type": "textarea", "label": "One action each of us will take:"}]'::jsonb, array['couples', 'review', 'connection']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('different-roles-fairness-map', 'Different Roles Fairness Map', 'couples'::resource_kind, 'A map for each partner to list household and emotional tasks and who carries them.', 'Use it to make unseen work visible so a couple can discuss it fairly.', array['Couples']::text[], 'Full session', 'List the tasks first, including mental load such as remembering and planning. Let each partner mark who does what and who thinks they do it. Differences in perception are the work; avoid ruling on who is right.', '[{"id": "f0", "type": "textarea", "label": "Partner A: tasks I carry, seen and unseen:"}, {"id": "f1", "type": "textarea", "label": "Partner B: tasks I carry, seen and unseen:"}, {"id": "f2", "type": "textarea", "label": "A task that surprised us:"}, {"id": "f3", "type": "textarea", "label": "One task we will move or share:"}]'::jsonb, array['couples', 'fairness', 'household']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('complaint-to-wish-conversion-sheet', 'Complaint to Wish Conversion Sheet', 'couples'::resource_kind, 'A sheet that turns a complaint into a wish stated positively.', 'Use it to help partners ask for what they want.', array['Couples']::text[], '25 minutes', 'Each partner writes a recent complaint and then turns it into what they wish for, in positive words. Read the wishes to each other. Ask how it feels to receive a wish versus a complaint.', '[{"id": "f0", "type": "textarea", "label": "Partner A: a complaint and my wish:"}, {"id": "f1", "type": "textarea", "label": "Partner B: a complaint and my wish:"}, {"id": "f2", "type": "textarea", "label": "What it was like to hear a wish:"}, {"id": "f3", "type": "textarea", "label": "A wish we will act on:"}]'::jsonb, array['couples', 'communication', 'wishes']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('shared-dreams-conversation-cards', 'Shared Dreams Conversation Cards', 'couples'::resource_kind, 'Cards of open questions about hopes for the coming years that partners answer in turn.', 'Use it to help a couple talk about what they want, not only what is wrong.', array['Couples']::text[], '30 minutes', 'Take turns drawing a card and answering while the other listens without fixing. Mark where dreams overlap and where they differ. If a difference sounds painful, note it for a later session rather than settling it on the spot.', '[{"id": "f0", "type": "textarea", "label": "Partner A: a dream I have for us:"}, {"id": "f1", "type": "textarea", "label": "Partner B: a dream I have for us:"}, {"id": "f2", "type": "textarea", "label": "Where our dreams overlap:"}, {"id": "f3", "type": "textarea", "label": "One step we could take toward a shared dream:"}]'::jsonb, array['couples', 'shared meaning', 'connection']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('feelings-postcard-writer', 'Feelings Postcard Writer', 'kids'::resource_kind, 'A child draws a postcard from the feeling and writes what it wants to say.', 'Use it to help a child give words to a feeling.', array['Children']::text[], '20 minutes', 'The child picks a feeling, draws a postcard picture on one side and dictates a message on the other. The parent reads it back kindly. If a child discloses harm, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Draw the picture on my postcard."}, {"id": "f1", "type": "textarea", "label": "Write what the feeling says."}, {"id": "f2", "type": "textarea", "label": "Draw who the postcard is for."}, {"id": "f3", "type": "textarea", "label": "Draw what I want to say back."}]'::jsonb, array['kids', 'feelings', 'drawing']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('bedtime-worry-paper-airplanes', 'Bedtime Worry Paper Airplanes', 'kids'::resource_kind, 'A child draws worries on paper, folds an airplane and launches it away.', 'Use it to give worries somewhere to go before bed.', array['Children']::text[], '20 minutes', 'The child draws or writes a worry, folds a plane and throws it across the room. The parent picks the planes up the next morning. Keep it playful. If a child discloses harm, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Draw a worry for my airplane."}, {"id": "f1", "type": "textarea", "label": "Draw where it flies."}, {"id": "f2", "type": "textarea", "label": "Draw how I feel after it flies away."}, {"id": "f3", "type": "textarea", "label": "Draw what I do at bedtime."}]'::jsonb, array['kids', 'worry', 'bedtime']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('pinwheel-breath-spinner-craft', 'Pinwheel Breath Spinner Craft', 'kids'::resource_kind, 'A child makes a pinwheel to spin with slow breaths.', 'Use it to give a child a visible way to practice slow breathing.', array['Children']::text[], '25 minutes', 'The child decorates paper and builds a pinwheel, then blows slowly to keep it spinning. The parent makes one too. Explain it is a tool and not a punishment. If a child discloses harm, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Draw my pinwheel and its colors."}, {"id": "f1", "type": "textarea", "label": "Draw how my breath moves it."}, {"id": "f2", "type": "textarea", "label": "Draw how my body feels after."}, {"id": "f3", "type": "textarea", "label": "Draw where I will keep it."}]'::jsonb, array['kids', 'calming', 'craft']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('courage-cape-maker', 'Courage Cape Maker', 'kids'::resource_kind, 'A child decorates a cape with symbols of their courage.', 'Use it to help a child connect with their own courage.', array['Children']::text[], '30 minutes', 'Offer fabric or paper and markers. The child adds symbols for times they were brave. The parent adds one moment they noticed. If a child discloses harm, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Draw a time I was brave."}, {"id": "f1", "type": "textarea", "label": "Draw my courage symbol."}, {"id": "f2", "type": "textarea", "label": "Draw who helps me be brave."}, {"id": "f3", "type": "textarea", "label": "Draw where I will wear my cape."}]'::jsonb, array['kids', 'courage', 'craft']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('kindness-compass-collage', 'Kindness Compass Collage', 'kids'::resource_kind, 'A child cuts and pastes pictures of kind acts around a compass for family kindness.', 'Use it to help a child notice and plan kind acts.', array['Children']::text[], '30 minutes', 'Provide magazines, glue and paper. The child chooses images of kind acts and places them around the compass. The parent adds one idea. Ask the child which one they might do this week and who would feel it.', '[{"id": "f0", "type": "textarea", "label": "Draw a kind thing someone did for me."}, {"id": "f1", "type": "textarea", "label": "Draw a kind thing I can do for a friend."}, {"id": "f2", "type": "textarea", "label": "Draw a kind thing I can do at home."}, {"id": "f3", "type": "textarea", "label": "Draw how I feel when I am kind."}]'::jsonb, array['kids', 'kindness', 'collage']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('feelings-freeze-frame-statues', 'Feelings Freeze-Frame Statues', 'game'::resource_kind, 'Players strike a pose for a feeling and the group guesses and discusses it.', 'Use it to help a group read body language.', array['Children', 'Teens', 'Groups']::text[], '20 minutes', 'A leader calls a feeling and everyone freezes in a pose. Rules: no words and no touching. Debrief on which poses looked alike and how the body shows feelings.', '[{"id": "f0", "type": "textarea", "label": "A pose I found easy:"}, {"id": "f1", "type": "textarea", "label": "One that looked different on others:"}, {"id": "f2", "type": "textarea", "label": "How I can tell a feeling from the body:"}, {"id": "f3", "type": "textarea", "label": "What I will notice this week:"}]'::jsonb, array['game', 'emotions', 'groups']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('coping-skill-bingo', 'Coping Skill Bingo', 'game'::resource_kind, 'A bingo card of coping skills where players mark a square after sharing a time they used it.', 'Use it to help a group trade coping ideas in a playful way.', array['Children', 'Teens', 'Groups']::text[], '25 minutes', 'Each square holds a skill such as walking or talking to a friend. A player marks a square by telling a time they used it. First to complete a line wins a small prize. Debrief on new skills picked up from others.', '[{"id": "f0", "type": "textarea", "label": "A skill I already use:"}, {"id": "f1", "type": "textarea", "label": "A skill I heard that I want to try:"}, {"id": "f2", "type": "textarea", "label": "A time a skill helped me:"}, {"id": "f3", "type": "textarea", "label": "Which skill I will try this week:"}]'::jsonb, array['game', 'coping skills', 'bingo']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('strengths-spotlight-toss', 'Strengths Spotlight Toss', 'game'::resource_kind, 'A beanbag toss where the catcher names a strength of the thrower.', 'Use it to help group members notice strengths in each other.', array['Teens', 'Groups']::text[], '15 minutes', 'Players stand in a circle and toss a beanbag. The catcher says one strength they see in the thrower, then throws it onward. Rules: only kind, true statements, and anyone can say pass. Debrief on how it felt to give and receive.', '[{"id": "f0", "type": "textarea", "label": "A strength someone named in me:"}, {"id": "f1", "type": "textarea", "label": "How it felt to hear it:"}, {"id": "f2", "type": "textarea", "label": "A strength I named in someone:"}, {"id": "f3", "type": "textarea", "label": "A strength I want to use this week:"}]'::jsonb, array['game', 'strengths', 'groups']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('problem-solving-escape-challenge', 'Problem-Solving Escape Challenge', 'game'::resource_kind, 'A group puzzle challenge where players divide roles and talk through a plan to solve clues in time.', 'Use it to help a group practice teamwork under mild pressure.', array['Teens', 'Groups']::text[], '30 minutes', 'Set a few clues or puzzles with a timer. Rules: everyone has a role, and each person must contribute at least once. After the game, debrief on who led, who listened, and how the group handled stress.', '[{"id": "f0", "type": "textarea", "label": "The role I took:"}, {"id": "f1", "type": "textarea", "label": "What helped us work together:"}, {"id": "f2", "type": "textarea", "label": "What got in our way:"}, {"id": "f3", "type": "textarea", "label": "What I would do differently next time:"}]'::jsonb, array['game', 'teamwork', 'problem-solving']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('opposite-day-role-play-game', 'Opposite Day Role-Play Game', 'game'::resource_kind, 'Players do a scene in the usual way and then in the opposite way and notice the difference.', 'Use it to help players see how tone and words change an interaction.', array['Teens', 'Groups']::text[], '20 minutes', 'Pair players for a simple scene such as asking for a turn. Round one, play it badly on purpose; round two, play it well. Rules: no insults and no touching. Debrief on what changed and which version they would want to receive.', '[{"id": "f0", "type": "textarea", "label": "The scene we played:"}, {"id": "f1", "type": "textarea", "label": "What the bad version felt like:"}, {"id": "f2", "type": "textarea", "label": "What the good version felt like:"}, {"id": "f3", "type": "textarea", "label": "One thing I will try in real life:"}]'::jsonb, array['game', 'role-play', 'social skills']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('safe-place-sensory-inventory', 'Safe Place Sensory Inventory', 'worksheet'::resource_kind, 'A sheet for listing the sights, sounds and textures of a place where a client feels settled.', 'Use it to build a present-focused place a client can return to in mind.', array['Adults', 'Teens']::text[], '25 minutes', 'Keep it to a real or imagined place that feels neutral to good; skip any place linked with hard memories. Ask for sensory details only. If the image brings distress, pause and orient to the room. This stays on stabilizing, not on recounting events.', '[{"id": "f0", "type": "textarea", "label": "A place where I feel settled:"}, {"id": "f1", "type": "textarea", "label": "What I see there:"}, {"id": "f2", "type": "textarea", "label": "What I hear and smell there:"}, {"id": "f3", "type": "textarea", "label": "How my body feels when I picture it:"}]'::jsonb, array['PTSD and trauma', 'grounding', 'safety']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('trigger-and-response-pattern-log', 'Trigger and Response Pattern Log', 'cbt'::resource_kind, 'A log of what happens before, during and after a reminder, with no need to describe the past event.', 'Use it to help a client notice patterns in present-day reminders and responses.', array['Adults']::text[], 'One week', 'The client records only the present: where they were, what they noticed in the body, and what helped. Do not ask for details of the past event. Review for patterns of time and place and pick one coping step to try next week.', '[{"id": "f0", "type": "textarea", "label": "Where I was and what I noticed:"}, {"id": "f1", "type": "textarea", "label": "What my body did:"}, {"id": "f2", "type": "textarea", "label": "What helped me come back to now:"}, {"id": "f3", "type": "textarea", "label": "A step I will try next time:"}]'::jsonb, array['PTSD and trauma', 'CBT', 'triggers', 'grounding']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('containment-imagery-practice', 'Containment Imagery Practice', 'dbt'::resource_kind, 'A guided practice of picturing a strong container for overwhelming material between sessions.', 'Use it to give a client a way to set distress aside until session.', array['Adults']::text[], '20 minutes', 'Walk the client through choosing a container, what it is made of, and where they will keep it. The focus is on pacing, not on putting memories in. If images of the past arise, return to the present with five senses.', '[{"id": "f0", "type": "textarea", "label": "The container I picture:"}, {"id": "f1", "type": "textarea", "label": "Where I keep it:"}, {"id": "f2", "type": "textarea", "label": "How I know when I need it:"}, {"id": "f3", "type": "textarea", "label": "What I do after I close it:"}]'::jsonb, array['PTSD and trauma', 'DBT', 'containment', 'pacing']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('quiet-signals-card-for-hard-days', 'Quiet Signals Card for Hard Days', 'couples'::resource_kind, 'A card of simple signals a partner uses to say what they need.', 'Use it to give partners a low-effort way to ask for support.', array['Couples']::text[], '25 minutes', 'Pick three signals such as a color or a word for space, company or a hug. Partner A and Partner B each keep a card. Do not ask for details of the past; keep to what helps now.', '[{"id": "f0", "type": "textarea", "label": "Partner A: my three signals and meanings:"}, {"id": "f1", "type": "textarea", "label": "Partner B: my three signals and meanings:"}, {"id": "f2", "type": "textarea", "label": "How we will respond to each:"}, {"id": "f3", "type": "textarea", "label": "When we will review the card:"}]'::jsonb, array['PTSD and trauma', 'couples', 'signals', 'support']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('small-pleasures-and-purposes-planner', 'Small Pleasures and Purposes Planner', 'act'::resource_kind, 'A planner pairing one small pleasure with one small purpose each day.', 'Use it to help a client rebuild a day with gentle steps.', array['Adults']::text[], 'One week', 'Each day the client picks a small pleasure and a small purpose, such as a short walk and watering a plant. Keep it manageable and present-focused. Review what felt possible and what did not.', '[{"id": "f0", "type": "textarea", "label": "Today''s small pleasure:"}, {"id": "f1", "type": "textarea", "label": "Today''s small purpose:"}, {"id": "f2", "type": "textarea", "label": "What made it easier or harder:"}, {"id": "f3", "type": "textarea", "label": "What I will keep for next week:"}]'::jsonb, array['PTSD and trauma', 'ACT', 'values', 'pacing']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('anxiety-early-warning-body-map', 'Anxiety Early Warning Body Map', 'worksheet'::resource_kind, 'A body outline for marking where anxiety shows up first.', 'Use it to help a client catch anxiety early.', array['Adults', 'Teens']::text[], '25 minutes', 'The client colors places in the body where anxiety shows up and numbers them in order. Pick the first sign as their cue to use a skill. Revisit the map when sensations change.', '[{"id": "f0", "type": "textarea", "label": "Where anxiety shows up first:"}, {"id": "f1", "type": "textarea", "label": "What comes next:"}, {"id": "f2", "type": "textarea", "label": "My cue to use a skill:"}, {"id": "f3", "type": "textarea", "label": "The skill I will try:"}]'::jsonb, array['anxiety', 'worksheet', 'body map', 'anxiety signals']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('probability-and-cost-estimation-sheet', 'Probability and Cost Estimation Sheet', 'cbt'::resource_kind, 'A sheet for estimating how likely a feared outcome is and how bad it would be to cope with.', 'Use it to compare a feared outcome with a realistic one.', array['Adults', 'Teens']::text[], '25 minutes', 'Have the client write the feared outcome, estimate likelihood, then list what they would do if it happened. Many clients find they underrate their coping. Avoid arguing; ask how they would know which estimate is closer.', '[{"id": "f0", "type": "textarea", "label": "The outcome I fear:"}, {"id": "f1", "type": "textarea", "label": "How likely I think it is, 0 to 100:"}, {"id": "f2", "type": "textarea", "label": "What I would do if it happened:"}, {"id": "f3", "type": "textarea", "label": "A realistic estimate now:"}]'::jsonb, array['anxiety', 'CBT', 'worry', 'estimation']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('worry-dragon-taming-drawing', 'Worry Dragon Taming Drawing', 'kids'::resource_kind, 'A child draws a worry dragon and then draws ways to make it smaller and friendlier.', 'Use it to help a child see a worry as something they can shrink.', array['Children']::text[], '25 minutes', 'Let the child make the dragon as big as the worry feels, then add a leash, a hat or a funny voice. The parent practices saying something calm to the dragon. Remind the clinician of reporting duties if a child shares harm.', '[{"id": "f0", "type": "textarea", "label": "Draw my worry dragon."}, {"id": "f1", "type": "textarea", "label": "Draw something that makes it smaller."}, {"id": "f2", "type": "textarea", "label": "Draw who helps me tame it."}, {"id": "f3", "type": "textarea", "label": "Draw what I do when it roars."}]'::jsonb, array['anxiety', 'kids', 'worry', 'drawing']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('opposite-action-for-avoidance-rehearsal', 'Opposite Action for Avoidance Rehearsal', 'dbt'::resource_kind, 'A rehearsal that pairs the urge to avoid with a small approach step.', 'Use it to practice taking one small step toward something avoided.', array['Adults', 'Teens']::text[], '25 minutes', 'Check that the fear does not match real danger. Plan the step, including body posture and breath. Rehearse in session, then plan it for the week. Review what happened without judging the size of the step.', '[{"id": "f0", "type": "textarea", "label": "What I am avoiding:"}, {"id": "f1", "type": "textarea", "label": "The small step toward it:"}, {"id": "f2", "type": "textarea", "label": "How I will stand and breathe:"}, {"id": "f3", "type": "textarea", "label": "What I noticed afterward:"}]'::jsonb, array['anxiety', 'DBT', 'avoidance', 'opposite action']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('maybe-jar-drawing-game', 'Maybe Jar Drawing Game', 'game'::resource_kind, 'Players draw slips with "maybe" situations and plan a response to each.', 'Use it to help a group rehearse flexible plans for unknowns.', array['Teens', 'Groups']::text[], '25 minutes', 'Fill a jar with slips such as a late bus or a changed plan. Rules: each player draws one and says a flexible next step. Debrief on how it felt to not know.', '[{"id": "f0", "type": "textarea", "label": "The maybe I drew:"}, {"id": "f1", "type": "textarea", "label": "My flexible next step:"}, {"id": "f2", "type": "textarea", "label": "What helped me stay calm:"}, {"id": "f3", "type": "textarea", "label": "A maybe from my own week:"}]'::jsonb, array['anxiety', 'game', 'uncertainty', 'groups']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('low-mood-day-menu-of-small-steps', 'Low-Mood Day Menu of Small Steps', 'worksheet'::resource_kind, 'A menu with starters, mains and sweets of tiny actions for days with little energy.', 'Use it to give a client choices for the days when everything feels heavy.', array['Adults', 'Teens']::text[], '20 minutes', 'Build the menu with the client on a better day, so it is ready for a harder one. Starters are five-minute steps. Make the menu theirs, with what truly appeals. Review it in session and update.', '[{"id": "f0", "type": "textarea", "label": "Starters that take five minutes:"}, {"id": "f1", "type": "textarea", "label": "Mains that take twenty:"}, {"id": "f2", "type": "textarea", "label": "Sweets that give me pleasure:"}, {"id": "f3", "type": "textarea", "label": "Where I will keep the menu:"}]'::jsonb, array['depression', 'worksheet', 'activation', 'mood']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('evidence-for-and-against-a-low-thought', 'Evidence For and Against a Low Thought', 'cbt'::resource_kind, 'A two-column sheet for weighing evidence about a bleak thought.', 'Use it to help a client test a low-mood thought with real examples.', array['Adults', 'Teens']::text[], '30 minutes', 'Ask for facts, not feelings, in each column, and invite a third column for what a good friend would say. Avoid forcing a bright view. Expect the against column to be harder to fill; help by asking about exceptions.', '[{"id": "f0", "type": "textarea", "label": "The thought:"}, {"id": "f1", "type": "textarea", "label": "Evidence for it:"}, {"id": "f2", "type": "textarea", "label": "Evidence against it:"}, {"id": "f3", "type": "textarea", "label": "What a friend would say:"}]'::jsonb, array['depression', 'CBT', 'mood', 'evidence']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('small-moments-of-meaning-log', 'Small Moments of Meaning Log', 'act'::resource_kind, 'A log for noting moments each day that felt worthwhile, even briefly.', 'Use it to help a client find value even on flat days.', array['Adults', 'Teens']::text[], 'One week', 'The client records one small moment a day and which value it touched. Do not require good feelings; only that it mattered. Review the week together and ask what they want more of.', '[{"id": "f0", "type": "textarea", "label": "A moment that mattered today:"}, {"id": "f1", "type": "textarea", "label": "The value it touched:"}, {"id": "f2", "type": "textarea", "label": "What I did or noticed:"}, {"id": "f3", "type": "textarea", "label": "More of this would look like:"}]'::jsonb, array['depression', 'ACT', 'values', 'mood']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('lifting-each-other-up-plan', 'Lifting Each Other Up Plan', 'couples'::resource_kind, 'Partners write what helps when one feels low and what the other can do.', 'Use it to give partners a shared way to respond to low mood.', array['Couples']::text[], '30 minutes', 'Each partner lists helpful and unhelpful responses, such as company versus advice. Agree on a signal. Include a line on when to bring in more help, and name 988 (call or text) in the plan for either partner.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what helps when I feel low:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what helps when I feel low:"}, {"id": "f2", "type": "textarea", "label": "What not to do or say:"}, {"id": "f3", "type": "textarea", "label": "If things feel unsafe, we can call or text 988 or reach out for help:"}]'::jsonb, array['depression', 'couples', 'support', 'mood']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('mood-mountain-trail-drawing', 'Mood Mountain Trail Drawing', 'kids'::resource_kind, 'A child draws a trail with ups and downs that match their week.', 'Use it to help a child show how their mood changed.', array['Children', 'Teens']::text[], '25 minutes', 'The child draws a mountain trail and marks high points and low points with days. The parent adds a rest stop. Note safety concerns for follow-up. If a child discloses harm, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Draw my trail this week."}, {"id": "f1", "type": "textarea", "label": "Draw a high point."}, {"id": "f2", "type": "textarea", "label": "Draw a low point."}, {"id": "f3", "type": "textarea", "label": "Draw a rest stop or helper on the trail."}]'::jsonb, array['depression', 'kids', 'mood', 'drawing']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('launch-pad-task-starter-sheet', 'Launch Pad Task Starter Sheet', 'worksheet'::resource_kind, 'A sheet for lowering the barrier to start a dreaded task.', 'Use it to help a client take the first two minutes of a task.', array['Adults', 'Teens']::text[], '20 minutes', 'Write the task, shrink it to the first two minutes, list what to gather and set a timer. Many clients find starting is the hard part. Review what worked and shrink the next step further if needed.', '[{"id": "f0", "type": "textarea", "label": "The task I am putting off:"}, {"id": "f1", "type": "textarea", "label": "The first two minutes look like:"}, {"id": "f2", "type": "textarea", "label": "What I need to gather:"}, {"id": "f3", "type": "textarea", "label": "When I will start:"}]'::jsonb, array['ADHD', 'worksheet', 'starting', 'focus']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('task-chunking-staircase-sheet', 'Task Chunking Staircase Sheet', 'cbt'::resource_kind, 'A staircase sheet that splits a big task into steps with a finish line for each.', 'Use it to help a client turn a large task into chunks.', array['Adults', 'Teens']::text[], '25 minutes', 'Draw stairs and write one chunk per stair, each with a clear finish. Pick the first stair and set a time. Review which stairs were too big and split them.', '[{"id": "f0", "type": "textarea", "label": "The big task:"}, {"id": "f1", "type": "textarea", "label": "The stairs from first to last:"}, {"id": "f2", "type": "textarea", "label": "The first stair and when:"}, {"id": "f3", "type": "textarea", "label": "A stair I may need to split:"}]'::jsonb, array['ADHD', 'CBT', 'chunking', 'planning']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('brain-break-menu-poster', 'Brain Break Menu Poster', 'kids'::resource_kind, 'A child decorates a poster of movement and sensory breaks to choose from.', 'Use it to give a child choices for short breaks during homework.', array['Children']::text[], '25 minutes', 'Offer markers and let the child draw breaks like jumping jacks or squeezing a ball. The parent posts it and offers a menu choice at break time. Keep breaks brief with a timer.', '[{"id": "f0", "type": "textarea", "label": "Draw a break that moves my body."}, {"id": "f1", "type": "textarea", "label": "Draw a break that calms me."}, {"id": "f2", "type": "textarea", "label": "Draw a break I can do at my desk."}, {"id": "f3", "type": "textarea", "label": "Draw how I get back to work."}]'::jsonb, array['ADHD', 'kids', 'breaks', 'poster']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('mindful-single-task-practice', 'Mindful Single-Task Practice', 'dbt'::resource_kind, 'A practice of doing one task with full attention for a short, set time.', 'Use it to build the habit of staying with one activity.', array['Adults', 'Teens']::text[], '15 minutes', 'Pick a small task and a timer. Each time attention wanders, the client notices and returns without scolding. Start with five minutes. The skill is the returning, not the staying.', '[{"id": "f0", "type": "textarea", "label": "The one task I chose:"}, {"id": "f1", "type": "textarea", "label": "How many times I wandered:"}, {"id": "f2", "type": "textarea", "label": "How I came back:"}, {"id": "f3", "type": "textarea", "label": "Where I could use this tomorrow:"}]'::jsonb, array['ADHD', 'DBT', 'mindfulness', 'focus']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('beat-the-timer-task-race', 'Beat the Timer Task Race', 'game'::resource_kind, 'A game where players race a timer on small tasks and set rewards.', 'Use it to make starting tasks feel more playful.', array['Children', 'Teens', 'Groups']::text[], '20 minutes', 'Players pick small tasks, set a timer and race it. Rules: only one task at a time and rewards are small. Debrief on which tasks the timer helped with and which it did not.', '[{"id": "f0", "type": "textarea", "label": "The task I raced:"}, {"id": "f1", "type": "textarea", "label": "How the timer felt:"}, {"id": "f2", "type": "textarea", "label": "A reward I chose:"}, {"id": "f3", "type": "textarea", "label": "Where I could use a timer this week:"}]'::jsonb, array['ADHD', 'game', 'timers', 'focus']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('substance-use-urge-delay-timeline', 'Substance Use Urge Delay Timeline', 'worksheet'::resource_kind, 'A timeline for recording a delay before acting on a substance use urge.', 'Use it to practice waiting and watching an urge.', array['Adults', 'Teens']::text[], 'One week', 'The client sets a delay such as ten minutes, notes what they did and what happened to the urge. A longer delay is not required to count. Review without judgment.', '[{"id": "f0", "type": "textarea", "label": "The urge and what set it off:"}, {"id": "f1", "type": "textarea", "label": "How long I delayed:"}, {"id": "f2", "type": "textarea", "label": "What I did in that time:"}, {"id": "f3", "type": "textarea", "label": "What happened to the urge:"}]'::jsonb, array['addiction', 'worksheet', 'urges', 'substance use']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('high-risk-situations-map', 'High-Risk Situations Map', 'cbt'::resource_kind, 'A map of people, places and moods linked with urges for substance use, with a plan for each.', 'Use it to plan ahead for situations that raise urges.', array['Adults']::text[], '30 minutes', 'Have the client list situations, rate risk and write a coping step for each. Treat a slip as information, not failure. Update the map after each session.', '[{"id": "f0", "type": "textarea", "label": "Situations that raise my urges:"}, {"id": "f1", "type": "textarea", "label": "How risky each feels, 0 to 10:"}, {"id": "f2", "type": "textarea", "label": "What I will do in each:"}, {"id": "f3", "type": "textarea", "label": "Who I can call:"}]'::jsonb, array['addiction', 'CBT', 'relapse prevention', 'urges']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('values-and-substance-use-choice-point', 'Values and Substance Use Choice Point', 'act'::resource_kind, 'A diagram for sorting moves toward and away from what matters.', 'Use it to help a client see which choices move toward their values.', array['Adults', 'Teens']::text[], '25 minutes', 'Draw a line: moves toward what matters, moves away. Place recent choices on it. Ask what the hooks were. Keep the tone curious and not shaming.', '[{"id": "f0", "type": "textarea", "label": "What matters to me:"}, {"id": "f1", "type": "textarea", "label": "A move toward it this week:"}, {"id": "f2", "type": "textarea", "label": "A move away from it:"}, {"id": "f3", "type": "textarea", "label": "What hooked me in that moment:"}]'::jsonb, array['addiction', 'ACT', 'choice point', 'values']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('rebuilding-trust-check-in-plan', 'Rebuilding Trust Check-In Plan', 'couples'::resource_kind, 'A weekly check-in for partners rebuilding trust around substance use.', 'Use it to give partners a structured way to talk about honesty and support.', array['Couples']::text[], 'Full session', 'Agree on the format: each partner speaks, the other reflects. Partner A and Partner B each name needs. Avoid it becoming an interrogation. Include what support looks like and what each will do if there is a slip.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I need to feel trust:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I need to feel trust:"}, {"id": "f2", "type": "textarea", "label": "What honesty looks like for us:"}, {"id": "f3", "type": "textarea", "label": "What we will do if there is a slip:"}]'::jsonb, array['addiction', 'couples', 'trust', 'substance use']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('party-plan-pre-mortem-game', 'Party Plan Pre-Mortem Game', 'game'::resource_kind, 'A game of planning ahead for what could happen at an event.', 'Use it to help a group plan for situations with substance use.', array['Teens', 'Groups']::text[], '25 minutes', 'Players imagine an event, name what could go wrong and share a plan, including an exit and a person to call. Rules: no shaming. Debrief on the plans that seem easy to use.', '[{"id": "f0", "type": "textarea", "label": "The event I imagined:"}, {"id": "f1", "type": "textarea", "label": "What could go wrong:"}, {"id": "f2", "type": "textarea", "label": "My plan and my exit:"}, {"id": "f3", "type": "textarea", "label": "Who I will call:"}]'::jsonb, array['addiction', 'game', 'planning', 'groups']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('anger-cost-and-gain-balance-sheet', 'Anger Cost and Gain Balance Sheet', 'worksheet'::resource_kind, 'A balance sheet of what anger gives a client and what it costs.', 'Use it to help a client weigh acting on anger.', array['Adults', 'Teens']::text[], '25 minutes', 'Write the short-term gains and the longer-term costs of a recent anger response. Anger usually protects something; ask what. Keep it nonjudgmental.', '[{"id": "f0", "type": "textarea", "label": "A recent time I got angry:"}, {"id": "f1", "type": "textarea", "label": "What anger gave me:"}, {"id": "f2", "type": "textarea", "label": "What it cost:"}, {"id": "f3", "type": "textarea", "label": "What I was protecting:"}]'::jsonb, array['anger management', 'worksheet', 'anger', 'cost and gain']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('hot-thought-reframe-sheet', 'Hot Thought Reframe Sheet', 'cbt'::resource_kind, 'A sheet for catching an angry thought and finding a fairer view.', 'Use it to loosen anger-fueling thoughts.', array['Adults', 'Teens']::text[], '30 minutes', 'Have the client name the trigger, the thought about the other person, and the demand behind it. Ask what else could be true. Do not talk the client out of the feeling.', '[{"id": "f0", "type": "textarea", "label": "What happened:"}, {"id": "f1", "type": "textarea", "label": "The thought I had:"}, {"id": "f2", "type": "textarea", "label": "Another way to see it:"}, {"id": "f3", "type": "textarea", "label": "What I want to do now:"}]'::jsonb, array['anger management', 'CBT', 'anger', 'reframing']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('self-soothe-pause-menu-for-anger', 'Self-Soothe Pause Menu for Anger', 'dbt'::resource_kind, 'A menu of quick pause actions to use as anger rises.', 'Use it to give a client choices for pausing.', array['Adults', 'Teens']::text[], '15 minutes', 'List pause actions across the five senses and movement. Try two in session. Pick the one the client will most likely use.', '[{"id": "f0", "type": "textarea", "label": "Pauses that I might use:"}, {"id": "f1", "type": "textarea", "label": "The two I tried:"}, {"id": "f2", "type": "textarea", "label": "Which worked better:"}, {"id": "f3", "type": "textarea", "label": "Where I will use it:"}]'::jsonb, array['anger management', 'DBT', 'self-soothe', 'anger']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('angry-energy-burner-chart', 'Angry Energy Burner Chart', 'kids'::resource_kind, 'A chart where a child picks safe ways to burn off angry energy.', 'Use it to help a child pick safe ways to release anger.', array['Children']::text[], '25 minutes', 'The child draws or lists ways such as pushing a wall or stomping. The parent practices one with them. If a child discloses harm, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Draw how angry energy feels."}, {"id": "f1", "type": "textarea", "label": "Draw a safe way to burn it."}, {"id": "f2", "type": "textarea", "label": "Draw another."}, {"id": "f3", "type": "textarea", "label": "Draw what I do after."}]'::jsonb, array['anger management', 'kids', 'anger', 'movement']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('anger-choices-red-light-game', 'Anger Choices Red Light Game', 'game'::resource_kind, 'A red light, green light game where the stop is practiced as a pause before reacting.', 'Use it to practice stopping in the middle of action.', array['Children', 'Teens', 'Groups']::text[], '20 minutes', 'Play the classic game. At each stop, the group names a pause step. Rules: take turns being the caller. Debrief on how it felt to stop quickly.', '[{"id": "f0", "type": "textarea", "label": "What I felt at red:"}, {"id": "f1", "type": "textarea", "label": "What helped me stop:"}, {"id": "f2", "type": "textarea", "label": "A time I could use it:"}, {"id": "f3", "type": "textarea", "label": "What I will try:"}]'::jsonb, array['anger management', 'game', 'self-control', 'groups']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('doubt-versus-values-daily-sheet', 'Doubt Versus Values Daily Sheet', 'worksheet'::resource_kind, 'A sheet comparing what doubt demands with what the client values.', 'Use it to help a client tell what doubt asks for from what they care about.', array['Adults', 'Teens']::text[], '25 minutes', 'Write what doubt demanded today and the value the client would rather serve. Note how long it took. Choose one small act toward the value.', '[{"id": "f0", "type": "textarea", "label": "What doubt demanded today:"}, {"id": "f1", "type": "textarea", "label": "What I value instead:"}, {"id": "f2", "type": "textarea", "label": "A small act toward it:"}, {"id": "f3", "type": "textarea", "label": "What I noticed:"}]'::jsonb, array['OCD', 'worksheet', 'values']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('exposure-ladder-with-response-prevention-steps', 'Exposure Ladder With Response Prevention Steps', 'cbt'::resource_kind, 'A ladder from easier to harder situations with a plan to not do the ritual.', 'Use it to plan gradual practice with the clinician''s guidance.', array['Adults', 'Teens']::text[], 'Full session', 'Build the ladder together, rating each step 0 to 100. Plan what the client will do instead of the ritual. Start low. The clinician decides pacing.', '[{"id": "f0", "type": "textarea", "label": "Situations by difficulty:"}, {"id": "f1", "type": "textarea", "label": "The first step:"}, {"id": "f2", "type": "textarea", "label": "What I will do instead of the ritual:"}, {"id": "f3", "type": "textarea", "label": "What I noticed afterward:"}]'::jsonb, array['OCD', 'CBT', 'exposure', 'response prevention']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('making-room-for-intrusive-thoughts-practice', 'Making Room for Intrusive Thoughts Practice', 'act'::resource_kind, 'A practice of letting a thought be there while doing a valued task.', 'Use it to help a client carry thoughts without acting on them.', array['Adults', 'Teens']::text[], '20 minutes', 'Pick a valued task and a thought that shows up. The client says "I am having the thought that..." and continues. Keep the humor light. Avoid using it to push thoughts away.', '[{"id": "f0", "type": "textarea", "label": "The thought that shows up:"}, {"id": "f1", "type": "textarea", "label": "The task I care about:"}, {"id": "f2", "type": "textarea", "label": "What I did with the thought:"}, {"id": "f3", "type": "textarea", "label": "What I noticed:"}]'::jsonb, array['OCD', 'ACT', 'intrusive thoughts', 'defusion']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('reducing-reassurance-together-plan', 'Reducing Reassurance Together Plan', 'couples'::resource_kind, 'A plan for partners to respond kindly to reassurance requests.', 'Use it to help partners agree on how to handle reassurance.', array['Couples']::text[], '30 minutes', 'Partner A and Partner B talk through what helps. Agree on a kind phrase that supports without repeating reassurance. Review how it feels in a week.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I ask for and why:"}, {"id": "f1", "type": "textarea", "label": "Partner B: how I feel when I am asked:"}, {"id": "f2", "type": "textarea", "label": "A kind phrase we will use:"}, {"id": "f3", "type": "textarea", "label": "How we will check in:"}]'::jsonb, array['OCD', 'couples', 'reassurance']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('worry-boss-puppet-show', 'Worry Boss Puppet Show', 'kids'::resource_kind, 'A child makes a puppet of the worry boss and practices not obeying it.', 'Use it to help a child step back from intrusive demands.', array['Children']::text[], '25 minutes', 'Make a paper-bag puppet. You voice the boss and the child answers. The parent learns not to join rituals. If a child discloses harm, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Draw my worry boss puppet."}, {"id": "f1", "type": "textarea", "label": "Draw what it says."}, {"id": "f2", "type": "textarea", "label": "Draw how I answer."}, {"id": "f3", "type": "textarea", "label": "Draw what I do instead."}]'::jsonb, array['OCD', 'kids', 'puppet']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('panic-aftermath-self-kindness-sheet', 'Panic Aftermath Self-Kindness Sheet', 'worksheet'::resource_kind, 'A sheet for what to do and say to oneself after a panic wave.', 'Use it to help a client treat themselves kindly after panic.', array['Adults', 'Teens']::text[], '20 minutes', 'Plan the hour after a wave: water, a gentle task and kind words. Many clients criticize themselves afterward. Rehearse the words.', '[{"id": "f0", "type": "textarea", "label": "What I tell myself after:"}, {"id": "f1", "type": "textarea", "label": "What I will do in the next hour:"}, {"id": "f2", "type": "textarea", "label": "Who I can tell:"}, {"id": "f3", "type": "textarea", "label": "What I learned this time:"}]'::jsonb, array['panic attacks', 'worksheet', 'self-kindness', 'panic']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('body-sensation-misinterpretation-sheet', 'Body Sensation Misinterpretation Sheet', 'cbt'::resource_kind, 'A sheet pairing a body sensation with the scary reading and a likelier one.', 'Use it to help a client see ordinary explanations for sensations.', array['Adults', 'Teens']::text[], '30 minutes', 'Write a sensation, the feared meaning and a more likely meaning. Practice in session. Avoid reassurance loops.', '[{"id": "f0", "type": "textarea", "label": "The sensation:"}, {"id": "f1", "type": "textarea", "label": "What I feared it meant:"}, {"id": "f2", "type": "textarea", "label": "Another likely reason:"}, {"id": "f3", "type": "textarea", "label": "How I will remind myself:"}]'::jsonb, array['panic attacks', 'CBT', 'sensations', 'panic']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('paced-breathing-and-temperature-skill-card', 'Paced Breathing and Temperature Skill Card', 'dbt'::resource_kind, 'A card pairing slow exhale breathing with a cool water reset.', 'Use it to give a client two quick body steps during panic.', array['Adults', 'Teens']::text[], '15 minutes', 'Practice in session. Breathe out longer than in, then splash cool water on the face. Do not use when it could cause harm for the client; check with their doctor.', '[{"id": "f0", "type": "textarea", "label": "When I will use it:"}, {"id": "f1", "type": "textarea", "label": "How the breathing felt:"}, {"id": "f2", "type": "textarea", "label": "How the cool water felt:"}, {"id": "f3", "type": "textarea", "label": "What I will try first:"}]'::jsonb, array['panic attacks', 'DBT', 'distress tolerance', 'breathing']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('what-to-do-when-panic-hits-partner-plan', 'What To Do When Panic Hits Partner Plan', 'couples'::resource_kind, 'Partners write a plan for how the other can help during a panic wave.', 'Use it to give partners clear steps and avoid hovering.', array['Couples']::text[], '25 minutes', 'Each writes what helps and what does not. Agree on a short script. Partner B practices staying calm. Revisit the plan after a wave.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what helps me:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I will say and do:"}, {"id": "f2", "type": "textarea", "label": "What not to do:"}, {"id": "f3", "type": "textarea", "label": "How we will debrief:"}]'::jsonb, array['panic attacks', 'couples', 'panic', 'support']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('sensation-exposure-circuit-game', 'Sensation Exposure Circuit Game', 'game'::resource_kind, 'A circuit of safe activities, such as spinning or stair climbing, to practice sensations.', 'Use it to practice feeling sensations safely.', array['Teens', 'Groups']::text[], '25 minutes', 'Choose safe activities and check health first. Players rate sensations and breathe. Rules: stop if unwell. The clinician leads the pace.', '[{"id": "f0", "type": "textarea", "label": "The activity I did:"}, {"id": "f1", "type": "textarea", "label": "The sensation:"}, {"id": "f2", "type": "textarea", "label": "How it changed:"}, {"id": "f3", "type": "textarea", "label": "What I learned:"}]'::jsonb, array['panic attacks', 'game', 'interoceptive', 'panic']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('family-routine-anchor-chart', 'Family Routine Anchor Chart', 'worksheet'::resource_kind, 'A chart for choosing three predictable anchors in a family''s day.', 'Use it to help parents set simple routines their family can keep.', array['Adults']::text[], '25 minutes', 'Ask the parent to pick three anchors, such as breakfast, homework and bedtime, and write who does what. Keep it small. Review it each week and tweak the parts that are not working.', '[{"id": "f0", "type": "textarea", "label": "The three anchors in our day:"}, {"id": "f1", "type": "textarea", "label": "Who does what at each:"}, {"id": "f2", "type": "textarea", "label": "What usually gets in the way:"}, {"id": "f3", "type": "textarea", "label": "One tweak I will try:"}]'::jsonb, array['parenting', 'worksheet', 'routine', 'parenting skills']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('parent-trigger-timeline-and-reset-plan', 'Parent Trigger Timeline and Reset Plan', 'cbt'::resource_kind, 'A timeline of a parenting trigger with a reset plan.', 'Use it to help parents notice triggers and plan a reset.', array['Adults']::text[], '25 minutes', 'Chart a recent trigger: before, the moment, after. Add a reset step such as breathing. Parents often find a pattern by time of day.', '[{"id": "f0", "type": "textarea", "label": "The trigger:"}, {"id": "f1", "type": "textarea", "label": "What I felt in my body:"}, {"id": "f2", "type": "textarea", "label": "My reset step:"}, {"id": "f3", "type": "textarea", "label": "What I want to do next time:"}]'::jsonb, array['parenting', 'CBT', 'triggers', 'parenting skills']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('repair-after-yelling-conversation-guide', 'Repair After Yelling Conversation Guide', 'act'::resource_kind, 'A guide for parents to repair with a child after losing their temper.', 'Use it to help parents model repair.', array['Adults']::text[], '25 minutes', 'Write a short repair: what happened, own it, what you will do next time. Practice aloud. Repair does not need to be perfect.', '[{"id": "f0", "type": "textarea", "label": "What happened:"}, {"id": "f1", "type": "textarea", "label": "What I will own:"}, {"id": "f2", "type": "textarea", "label": "What I will say:"}, {"id": "f3", "type": "textarea", "label": "What I will do next time:"}]'::jsonb, array['parenting', 'ACT', 'repair', 'parenting skills']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('family-rules-poster-we-make-together', 'Family Rules Poster We Make Together', 'kids'::resource_kind, 'A family decorates a poster of three or four positive rules.', 'Use it to give a family shared rules that the child helped write.', array['Children', 'Adults']::text[], '30 minutes', 'The child draws and the parent writes the rules in positive words, such as "we use gentle hands". Post it at home. The parent models following the rules. Follow your reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw our family."}, {"id": "f1", "type": "textarea", "label": "Draw a rule we agree on."}, {"id": "f2", "type": "textarea", "label": "Draw what happens when we follow it."}, {"id": "f3", "type": "textarea", "label": "Draw how we fix it when we forget."}]'::jsonb, array['parenting', 'kids', 'family', 'rules']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('praise-detective-game-for-parents', 'Praise Detective Game for Parents', 'game'::resource_kind, 'A game where parents look for and name small things a child does right.', 'Use it to build the habit of noticing good behavior.', array['Adults', 'Groups']::text[], 'Five minutes daily', 'Parents get a point for each specific praise they give in a day. Rules: be specific and sincere. Debrief on what the child did in response.', '[{"id": "f0", "type": "textarea", "label": "Praise I gave today:"}, {"id": "f1", "type": "textarea", "label": "How my child responded:"}, {"id": "f2", "type": "textarea", "label": "A praise I want to give more:"}, {"id": "f3", "type": "textarea", "label": "How I felt giving it:"}]'::jsonb, array['parenting', 'game', 'praise', 'parenting skills']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('postpartum-week-rest-and-help-plan', 'Postpartum Week Rest and Help Plan', 'worksheet'::resource_kind, 'A plan for sleep, meals and help for the first weeks with a new baby.', 'Use it to help a new parent line up rest and support.', array['Adults', 'Couples']::text[], '30 minutes', 'Build the plan with the parent, including who brings meals and who takes a night shift. Ask what they would find hard to accept help with. If the parent mentions thoughts of harm, name 988 (call or text) and follow up in session.', '[{"id": "f0", "type": "textarea", "label": "Who can help and with what:"}, {"id": "f1", "type": "textarea", "label": "My rest plan:"}, {"id": "f2", "type": "textarea", "label": "What I will say no to:"}, {"id": "f3", "type": "textarea", "label": "If I feel unsafe I can call or text 988 or tell someone now:"}]'::jsonb, array['perinatal and postpartum', 'worksheet', 'support', 'rest']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('comparison-trap-social-media-thought-sheet', 'Comparison Trap Social Media Thought Sheet', 'cbt'::resource_kind, 'A sheet for catching comparison thoughts after seeing other parents online.', 'Use it to help a new parent notice comparison.', array['Adults']::text[], '25 minutes', 'Name what was seen, the comparison and what the picture leaves out. Write a kinder line. Consider a break from accounts that stir it up.', '[{"id": "f0", "type": "textarea", "label": "What I saw:"}, {"id": "f1", "type": "textarea", "label": "The comparison I made:"}, {"id": "f2", "type": "textarea", "label": "What is left out of the picture:"}, {"id": "f3", "type": "textarea", "label": "A kinder line:"}]'::jsonb, array['perinatal and postpartum', 'CBT', 'comparison', 'new parent']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('making-space-for-mixed-feelings-practice', 'Making Space for Mixed Feelings Practice', 'act'::resource_kind, 'A practice of holding love and exhaustion together.', 'Use it to help a parent accept mixed feelings about parenthood.', array['Adults']::text[], '20 minutes', 'Ask the parent to name all the feelings present, not choosing among them. Practice saying "and". Do not push for gratitude.', '[{"id": "f0", "type": "textarea", "label": "Feelings I have right now:"}, {"id": "f1", "type": "textarea", "label": "The ones I feel guilty about:"}, {"id": "f2", "type": "textarea", "label": "Saying \"and\" for both:"}, {"id": "f3", "type": "textarea", "label": "What I value in this season:"}]'::jsonb, array['perinatal and postpartum', 'ACT', 'mixed feelings', 'new parent']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('night-shift-and-feeding-fairness-plan', 'Night Shift and Feeding Fairness Plan', 'couples'::resource_kind, 'Partners write who covers what at night and how they will swap.', 'Use it to help partners share night care and stay connected.', array['Couples']::text[], '25 minutes', 'Partner A and Partner B list tasks and agree on shifts. Add one check-in a day that is not about the baby. Adjust weekly.', '[{"id": "f0", "type": "textarea", "label": "Partner A: nights I can cover:"}, {"id": "f1", "type": "textarea", "label": "Partner B: nights I can cover:"}, {"id": "f2", "type": "textarea", "label": "Our daily check-in:"}, {"id": "f3", "type": "textarea", "label": "What we will review next week:"}]'::jsonb, array['perinatal and postpartum', 'couples', 'sleep', 'new parent']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('tiny-joy-treasure-hunt', 'Tiny Joy Treasure Hunt', 'game'::resource_kind, 'A hunt for small enjoyable moments each day.', 'Use it to help a new parent notice small bright spots.', array['Adults']::text[], 'Five minutes daily', 'The parent notes three tiny joys a day, such as a warm drink. Rules: small counts, and no need for them to be big. Debrief on patterns.', '[{"id": "f0", "type": "textarea", "label": "Joy one:"}, {"id": "f1", "type": "textarea", "label": "Joy two:"}, {"id": "f2", "type": "textarea", "label": "Joy three:"}, {"id": "f3", "type": "textarea", "label": "What I noticed:"}]'::jsonb, array['perinatal and postpartum', 'game', 'joy', 'new parent']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('compliment-deflection-practice-sheet', 'Compliment Deflection Practice Sheet', 'worksheet'::resource_kind, 'A sheet for practicing accepting a compliment.', 'Use it to help a client take in positive feedback.', array['Adults', 'Teens']::text[], '20 minutes', 'Record compliments received and how the client deflected. Practice saying "thank you." Notice how it feels.', '[{"id": "f0", "type": "textarea", "label": "A compliment I got:"}, {"id": "f1", "type": "textarea", "label": "How I responded:"}, {"id": "f2", "type": "textarea", "label": "How I could simply accept it:"}, {"id": "f3", "type": "textarea", "label": "How it felt to practice:"}]'::jsonb, array['self-esteem', 'worksheet', 'compliments', 'self-worth']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('inner-critic-versus-fair-coach-sheet', 'Inner Critic Versus Fair Coach Sheet', 'cbt'::resource_kind, 'A sheet that rewrites critic lines in a fair coach''s voice.', 'Use it to shift self-talk to a fair tone.', array['Adults', 'Teens']::text[], '25 minutes', 'Write a critic line, then what a fair coach would say. Practice saying it aloud. A coach is honest but not harsh.', '[{"id": "f0", "type": "textarea", "label": "What my critic says:"}, {"id": "f1", "type": "textarea", "label": "What a fair coach would say:"}, {"id": "f2", "type": "textarea", "label": "How each feels:"}, {"id": "f3", "type": "textarea", "label": "A line I will keep:"}]'::jsonb, array['self-esteem', 'CBT', 'self-talk', 'self-compassion']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('self-compassion-break-practice', 'Self-Compassion Break Practice', 'act'::resource_kind, 'A three-step pause: notice the hurt, remember others share it, offer kind words.', 'Use it to give a client a short kind reply to themselves.', array['Adults', 'Teens']::text[], '15 minutes', 'Walk through the three steps with a recent moment. Let the client choose the words. Some find a hand on the chest helpful; some do not.', '[{"id": "f0", "type": "textarea", "label": "What hurt:"}, {"id": "f1", "type": "textarea", "label": "Who else might feel this:"}, {"id": "f2", "type": "textarea", "label": "Kind words I could say:"}, {"id": "f3", "type": "textarea", "label": "When I will try this:"}]'::jsonb, array['self-esteem', 'ACT', 'self-compassion', 'pause']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('all-about-me-shield', 'All About Me Shield', 'kids'::resource_kind, 'A child draws a shield with things they are good at and love.', 'Use it to help a child see strengths and what matters.', array['Children', 'Teens']::text[], '30 minutes', 'Divide a shield into four parts. The parent adds one thing they love about the child. Follow your reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw something I am good at."}, {"id": "f1", "type": "textarea", "label": "Draw something I love."}, {"id": "f2", "type": "textarea", "label": "Draw something kind I did."}, {"id": "f3", "type": "textarea", "label": "Draw what a friend likes about me."}]'::jsonb, array['self-esteem', 'kids', 'strengths', 'drawing']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('compliment-mailbox-game', 'Compliment Mailbox Game', 'game'::resource_kind, 'Group members drop kind notes into mailboxes and read their own at the end.', 'Use it to give each person warm and specific feedback.', array['Teens', 'Groups']::text[], '25 minutes', 'Each player writes one kind specific note per member. Rules: true, kind, and specific. Debrief on how it felt to read them.', '[{"id": "f0", "type": "textarea", "label": "A note that surprised me:"}, {"id": "f1", "type": "textarea", "label": "How it felt to read them:"}, {"id": "f2", "type": "textarea", "label": "A note I wrote:"}, {"id": "f3", "type": "textarea", "label": "What I will remember:"}]'::jsonb, array['self-esteem', 'game', 'compliments', 'groups']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('post-event-mental-replay-review', 'Post-Event Mental Replay Review', 'worksheet'::resource_kind, 'A review sheet for the replay after a social event.', 'Use it to help a client check the replay against what happened.', array['Adults', 'Teens']::text[], '25 minutes', 'List what the client replays, what actually happened and what others likely noticed. Then plan to let go of the replay with a task.', '[{"id": "f0", "type": "textarea", "label": "What I replay:"}, {"id": "f1", "type": "textarea", "label": "What actually happened:"}, {"id": "f2", "type": "textarea", "label": "What others likely noticed:"}, {"id": "f3", "type": "textarea", "label": "What I will do instead of replaying:"}]'::jsonb, array['social anxiety', 'worksheet', 'rumination', 'social']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('safety-behaviors-drop-experiment', 'Safety Behaviors Drop Experiment', 'cbt'::resource_kind, 'An experiment dropping one safety behavior in a conversation.', 'Use it to test whether a safety behavior is needed.', array['Adults', 'Teens']::text[], 'Full session', 'Pick a safety behavior, such as rehearsing lines. Drop it for one conversation. Compare predictions with outcomes.', '[{"id": "f0", "type": "textarea", "label": "The safety behavior:"}, {"id": "f1", "type": "textarea", "label": "What I predicted:"}, {"id": "f2", "type": "textarea", "label": "What happened:"}, {"id": "f3", "type": "textarea", "label": "What I learned:"}]'::jsonb, array['social anxiety', 'CBT', 'safety behaviors', 'experiment']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('showing-up-anyway-value-plan', 'Showing Up Anyway Value Plan', 'act'::resource_kind, 'A plan to go to an event with a value in mind, anxiety allowed.', 'Use it to help a client act on values while anxious.', array['Adults', 'Teens']::text[], '25 minutes', 'Choose an event, a value and a willingness rating. Plan a small action, like asking one question. Review without judging performance.', '[{"id": "f0", "type": "textarea", "label": "The event:"}, {"id": "f1", "type": "textarea", "label": "The value I bring:"}, {"id": "f2", "type": "textarea", "label": "The anxiety I will make room for:"}, {"id": "f3", "type": "textarea", "label": "The small action:"}]'::jsonb, array['social anxiety', 'ACT', 'values', 'social']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('pre-event-pep-talk-partner-script', 'Pre-Event Pep Talk Partner Script', 'couples'::resource_kind, 'A script for a partner to give a short encouraging chat before an event.', 'Use it to help partners encourage each other.', array['Couples']::text[], '20 minutes', 'Partner A writes what encouragement helps and Partner B writes a script. Practice in session. Avoid pushing.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what encouragement helps:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I will say:"}, {"id": "f2", "type": "textarea", "label": "What not to say:"}, {"id": "f3", "type": "textarea", "label": "How we will debrief:"}]'::jsonb, array['social anxiety', 'couples', 'encouragement', 'social']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('ask-three-questions-conversation-game', 'Ask Three Questions Conversation Game', 'game'::resource_kind, 'A game where players ask three questions to learn about someone.', 'Use it to practice curiosity in conversation.', array['Teens', 'Groups']::text[], '20 minutes', 'Pairs ask three follow-up questions about a topic. Rules: listen and no interrupting. Debrief on what was learned.', '[{"id": "f0", "type": "textarea", "label": "A question I asked:"}, {"id": "f1", "type": "textarea", "label": "What I learned:"}, {"id": "f2", "type": "textarea", "label": "How it felt:"}, {"id": "f3", "type": "textarea", "label": "Where I will try it:"}]'::jsonb, array['social anxiety', 'game', 'curiosity', 'groups']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('grief-anniversary-and-holiday-planner', 'Grief Anniversary and Holiday Planner', 'worksheet'::resource_kind, 'A planner for difficult dates and how to spend them.', 'Use it to help a client plan for anniversaries and holidays.', array['Adults', 'Teens']::text[], '30 minutes', 'List dates, who to be with and a ritual. Leave room to change plans. If hopeless thoughts arise, name 988 (call or text).', '[{"id": "f0", "type": "textarea", "label": "The date:"}, {"id": "f1", "type": "textarea", "label": "How I want to spend it:"}, {"id": "f2", "type": "textarea", "label": "Who can be with me:"}, {"id": "f3", "type": "textarea", "label": "If I feel unsafe I can call or text 988 or tell someone now:"}]'::jsonb, array['grief and loss', 'worksheet', 'anniversaries', 'grief']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('grief-guilt-thought-check', 'Grief Guilt Thought Check', 'cbt'::resource_kind, 'A sheet for testing "I should have..." thoughts.', 'Use it to look at guilt thoughts with a fairer lens.', array['Adults', 'Teens']::text[], '30 minutes', 'Write the guilt thought, what the client knew then, and what a friend would say. Honor love under the guilt. Do not rush to relieve it.', '[{"id": "f0", "type": "textarea", "label": "The thought:"}, {"id": "f1", "type": "textarea", "label": "What I knew at the time:"}, {"id": "f2", "type": "textarea", "label": "What a friend would say:"}, {"id": "f3", "type": "textarea", "label": "What the guilt tells me I cared about:"}]'::jsonb, array['grief and loss', 'CBT', 'guilt', 'grief']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('making-room-for-waves-of-grief-practice', 'Making Room for Waves of Grief Practice', 'act'::resource_kind, 'A practice of letting waves of grief come and go.', 'Use it to help a client carry grief while living.', array['Adults']::text[], '20 minutes', 'Ask where grief shows in the body. Breathe around it. Link to what the pain says about love. If thoughts of self-harm arise, name 988 (call or text).', '[{"id": "f0", "type": "textarea", "label": "Where I feel it:"}, {"id": "f1", "type": "textarea", "label": "What it says about my love:"}, {"id": "f2", "type": "textarea", "label": "What I do when it comes:"}, {"id": "f3", "type": "textarea", "label": "If I feel unsafe I can call or text 988 or tell someone now:"}]'::jsonb, array['grief and loss', 'ACT', 'waves', 'grief']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('missing-you-letter-drawing', 'Missing You Letter Drawing', 'kids'::resource_kind, 'A child draws a picture letter to a person who died.', 'Use it to give a child a way to say what they miss.', array['Children']::text[], '25 minutes', 'The child draws and dictates a message. The parent reads it with them. If a child discloses harm, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Draw the person."}, {"id": "f1", "type": "textarea", "label": "Draw what I miss."}, {"id": "f2", "type": "textarea", "label": "Draw what I want to tell them."}, {"id": "f3", "type": "textarea", "label": "Draw who I can tell."}]'::jsonb, array['grief and loss', 'kids', 'letter', 'grief']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('remembering-together-circle', 'Remembering Together Circle', 'game'::resource_kind, 'Group members take turns sharing a memory with a passed object.', 'Use it to let a group share memories.', array['Adults', 'Teens', 'Groups']::text[], '30 minutes', 'Pass a candle or stone. Rules: share if you wish, and no advice. Debrief on what it was like to listen.', '[{"id": "f0", "type": "textarea", "label": "A memory I shared:"}, {"id": "f1", "type": "textarea", "label": "What I heard:"}, {"id": "f2", "type": "textarea", "label": "How I felt:"}, {"id": "f3", "type": "textarea", "label": "What I will carry:"}]'::jsonb, array['grief and loss', 'game', 'memory', 'groups']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('relationship-pattern-loop-map', 'Relationship Pattern Loop Map', 'worksheet'::resource_kind, 'A map of a repeating pattern between two people.', 'Use it to help a client see a cycle.', array['Adults']::text[], '30 minutes', 'Draw the loop: trigger, reaction, response, back. Find a point to step out. Keep to the client''s side.', '[{"id": "f0", "type": "textarea", "label": "The trigger:"}, {"id": "f1", "type": "textarea", "label": "My reaction:"}, {"id": "f2", "type": "textarea", "label": "Their response:"}, {"id": "f3", "type": "textarea", "label": "Where I could step out:"}]'::jsonb, array['relationship issues', 'worksheet', 'patterns', 'relationships']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('mind-reading-check-in-relationships', 'Mind-Reading Check in Relationships', 'cbt'::resource_kind, 'A sheet for testing guesses about what a partner thinks.', 'Use it to check assumptions before reacting.', array['Adults']::text[], '25 minutes', 'Have the client write the guess about what their partner thinks, the evidence for it, and one question they could ask instead. Practice asking aloud in session, since many clients skip this step. Avoid turning the question into a demand for reassurance.', '[{"id": "f0", "type": "textarea", "label": "What I assumed:"}, {"id": "f1", "type": "textarea", "label": "Evidence:"}, {"id": "f2", "type": "textarea", "label": "A question to ask:"}, {"id": "f3", "type": "textarea", "label": "What they said:"}]'::jsonb, array['relationship issues', 'CBT', 'assumptions', 'relationships']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('validation-phrases-practice-sheet', 'Validation Phrases Practice Sheet', 'dbt'::resource_kind, 'A sheet of validating phrases to practice.', 'Use it to build validation skills.', array['Adults', 'Teens']::text[], '25 minutes', 'Practice phrases such as "that makes sense" or "I can see why that hurt," then role-play a real situation with the client in each role. Remind them validation is not agreement. Ask which phrases felt natural and which felt forced.', '[{"id": "f0", "type": "textarea", "label": "A situation:"}, {"id": "f1", "type": "textarea", "label": "A validating phrase:"}, {"id": "f2", "type": "textarea", "label": "How it felt:"}, {"id": "f3", "type": "textarea", "label": "Where I will use it:"}]'::jsonb, array['relationship issues', 'DBT', 'validation', 'interpersonal effectiveness']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('appreciation-and-complaint-ratio-chart', 'Appreciation and Complaint Ratio Chart', 'couples'::resource_kind, 'Partners track appreciations and complaints through the week.', 'Use it to build more appreciation.', array['Couples']::text[], 'One week', 'Partner A and Partner B each tally appreciations they give and complaints they voice during the week, then share the chart in session. The aim is noticing and adding warmth, not scorekeeping. If the chart becomes ammunition, shift to a single shared appreciation habit.', '[{"id": "f0", "type": "textarea", "label": "Partner A: appreciations I gave:"}, {"id": "f1", "type": "textarea", "label": "Partner B: appreciations I gave:"}, {"id": "f2", "type": "textarea", "label": "What I noticed:"}, {"id": "f3", "type": "textarea", "label": "One more I will give:"}]'::jsonb, array['relationship issues', 'couples', 'appreciation', 'Gottman']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('boundary-role-play-cards', 'Boundary Role-Play Cards', 'game'::resource_kind, 'Cards with scenarios to practice kind firm boundaries.', 'Use it to practice setting boundaries.', array['Teens', 'Groups']::text[], '25 minutes', 'Draw a scenario card, play it out with a kind firm boundary, then swap roles so each player feels both sides. Rules: respect, no insults, and anyone can stop. Debrief on tone and body language, and which words felt easiest to keep for real life.', '[{"id": "f0", "type": "textarea", "label": "The scenario:"}, {"id": "f1", "type": "textarea", "label": "My boundary:"}, {"id": "f2", "type": "textarea", "label": "How it felt:"}, {"id": "f3", "type": "textarea", "label": "Where I will use it:"}]'::jsonb, array['relationship issues', 'game', 'boundaries', 'groups']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('safety-and-support-inventory', 'Safety and Support Inventory', 'worksheet'::resource_kind, 'A list of safe people, places and steps now.', 'Use it to help a client map present safety and support.', array['Adults', 'Teens']::text[], '30 minutes', 'Stay on the present: who is safe, where they feel safe and what helps. Do not ask for details of what happened. Go at the client''s pace. If safety is a concern, name 988 (call or text).', '[{"id": "f0", "type": "textarea", "label": "People I feel safe with:"}, {"id": "f1", "type": "textarea", "label": "Places I feel safe:"}, {"id": "f2", "type": "textarea", "label": "What helps when I feel unsafe:"}, {"id": "f3", "type": "textarea", "label": "If I feel unsafe I can call or text 988 or tell someone now:"}]'::jsonb, array['sexual abuse', 'worksheet', 'safety', 'support']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('grounding-with-the-present-room-card', 'Grounding With the Present Room Card', 'dbt'::resource_kind, 'A card for naming things in the room to return to now.', 'Use it to help a client return to the present.', array['Adults', 'Teens']::text[], '15 minutes', 'Practice with five things seen, four heard and so on. Keep eyes open if closing them is hard. Let the client set the pace.', '[{"id": "f0", "type": "textarea", "label": "Five things I see:"}, {"id": "f1", "type": "textarea", "label": "Four I hear:"}, {"id": "f2", "type": "textarea", "label": "Three I touch:"}, {"id": "f3", "type": "textarea", "label": "How my body feels now:"}]'::jsonb, array['sexual abuse', 'DBT', 'grounding', 'present']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('windows-of-comfort-pacing-scale', 'Windows of Comfort Pacing Scale', 'act'::resource_kind, 'A scale for noticing how much feels manageable.', 'Use it to help a client pace their work.', array['Adults', 'Teens']::text[], '20 minutes', 'Draw a scale from too little to too much and mark the middle zone. Choose pacing accordingly. No details of the past are needed. Name 988 (call or text) if safety is a concern.', '[{"id": "f0", "type": "textarea", "label": "Signs I am in my comfort zone:"}, {"id": "f1", "type": "textarea", "label": "Signs it is too much:"}, {"id": "f2", "type": "textarea", "label": "What helps me back:"}, {"id": "f3", "type": "textarea", "label": "If I feel unsafe I can call or text 988 or tell someone now:"}]'::jsonb, array['sexual abuse', 'ACT', 'pacing', 'safety']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('body-safety-rules-flip-book', 'Body Safety Rules Flip Book', 'kids'::resource_kind, 'A child makes a small flip book of body safety rules they can say aloud.', 'Use it to help a child know the rules of body safety.', array['Children']::text[], '25 minutes', 'Fold paper into a small flip book with one rule per page, such as "my body belongs to me" and "tell a safe adult." The parent reviews it with the child. Do not ask for details; if a child discloses, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Draw a rule about my body."}, {"id": "f1", "type": "textarea", "label": "Draw an adult I can tell."}, {"id": "f2", "type": "textarea", "label": "Draw what I do if I feel unsafe."}, {"id": "f3", "type": "textarea", "label": "Draw the cover of my flip book."}]'::jsonb, array['sexual abuse', 'kids', 'body safety', 'flip book']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('pacing-and-consent-check-in-guide', 'Pacing and Consent Check-In Guide', 'couples'::resource_kind, 'A guide for partners to set pace and signals around closeness.', 'Use it to help partners agree on pacing and consent signals.', array['Couples']::text[], '30 minutes', 'Partner A and Partner B agree on stop words and check-ins. Never ask for details of abuse. Go slowly; the survivor sets the pace.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what helps me feel safe:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I will do:"}, {"id": "f2", "type": "textarea", "label": "Our stop word:"}, {"id": "f3", "type": "textarea", "label": "How we will check in:"}]'::jsonb, array['sexual abuse', 'couples', 'pacing', 'consent']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('personal-coping-skills-menu', 'Personal Coping Skills Menu', 'worksheet'::resource_kind, 'A menu of skills sorted by body, mind, people and play.', 'Use it to help a client pick coping skills that fit.', array['Adults', 'Teens']::text[], '25 minutes', 'Sort ideas into body, mind, people and play, then have the client star three that fit their life. Try one in session so it is more than a list. Check whether the starred skills are realistic for the places where stress actually shows up.', '[{"id": "f0", "type": "textarea", "label": "Skills for my body:"}, {"id": "f1", "type": "textarea", "label": "Skills for my mind:"}, {"id": "f2", "type": "textarea", "label": "Skills with people:"}, {"id": "f3", "type": "textarea", "label": "Three I starred:"}]'::jsonb, array['worksheet', 'coping skills', 'menu']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('cue-and-response-coping-plan-deck', 'Cue and Response Coping Plan Deck', 'cbt'::resource_kind, 'Cards linking a stress cue to a chosen coping action.', 'Use it to prepare coping responses in advance.', array['Adults', 'Teens']::text[], '20 minutes', 'Write cue and response cards, such as "If I get stuck, then I will stretch." Carry them. Review which were used.', '[{"id": "f0", "type": "textarea", "label": "A cue:"}, {"id": "f1", "type": "textarea", "label": "My then:"}, {"id": "f2", "type": "textarea", "label": "Another pair:"}, {"id": "f3", "type": "textarea", "label": "Which I used:"}]'::jsonb, array['coping skills', 'CBT', 'if-then', 'planning']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('radical-acceptance-body-posture-practice', 'Radical Acceptance Body Posture Practice', 'dbt'::resource_kind, 'A practice using a relaxed posture to support accepting reality.', 'Use it to give a client a body-based aid for acceptance.', array['Adults', 'Teens']::text[], '20 minutes', 'Try half-smile and open hands while naming a situation that cannot change. Notice the body. Offer it as an aid, not a demand.', '[{"id": "f0", "type": "textarea", "label": "What I am fighting:"}, {"id": "f1", "type": "textarea", "label": "My posture:"}, {"id": "f2", "type": "textarea", "label": "What changed:"}, {"id": "f3", "type": "textarea", "label": "Where I will use it:"}]'::jsonb, array['coping skills', 'DBT', 'radical acceptance', 'body']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('cozy-calm-corner-blueprint', 'Cozy Calm Corner Blueprint', 'kids'::resource_kind, 'A child designs a calm corner at home.', 'Use it to give a child a place to settle.', array['Children']::text[], '30 minutes', 'Draw a plan for a corner with pillows and a book. The parent builds it. If a child discloses harm, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Draw my calm corner."}, {"id": "f1", "type": "textarea", "label": "Draw what is in it."}, {"id": "f2", "type": "textarea", "label": "Draw when I use it."}, {"id": "f3", "type": "textarea", "label": "Draw who visits."}]'::jsonb, array['coping skills', 'kids', 'calm corner', 'craft']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('stress-ball-toss-coping-chain', 'Stress Ball Toss Coping Chain', 'game'::resource_kind, 'Players toss a ball and name a coping skill to build a chain.', 'Use it to generate coping ideas as a group.', array['Children', 'Teens', 'Groups']::text[], '15 minutes', 'Players stand in a circle and toss a ball, naming a coping skill as they throw. Rules: no repeats, and anyone can say pass. Debrief on favorite skills heard and which one each person will try this week.', '[{"id": "f0", "type": "textarea", "label": "A skill I named:"}, {"id": "f1", "type": "textarea", "label": "A skill I want to try:"}, {"id": "f2", "type": "textarea", "label": "How it felt:"}, {"id": "f3", "type": "textarea", "label": "My plan:"}]'::jsonb, array['coping skills', 'game', 'groups']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('phobia-safety-behavior-inventory', 'Phobia Safety-Behavior Inventory', 'worksheet'::resource_kind, 'A list of things a client does to feel safer around a fear.', 'Use it to see how safety behaviors shape a fear.', array['Adults', 'Teens']::text[], '25 minutes', 'List what the client does, how it helps and what it costs. Choose one to drop in a later step with the clinician.', '[{"id": "f0", "type": "textarea", "label": "What I fear:"}, {"id": "f1", "type": "textarea", "label": "What I do to feel safer:"}, {"id": "f2", "type": "textarea", "label": "What it costs:"}, {"id": "f3", "type": "textarea", "label": "One I might drop:"}]'::jsonb, array['phobias', 'worksheet', 'safety behaviors', 'phobia']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('fear-prediction-versus-outcome-log', 'Fear Prediction Versus Outcome Log', 'cbt'::resource_kind, 'A log comparing predictions with what happened.', 'Use it to compare predictions with real outcomes.', array['Adults', 'Teens']::text[], 'One week', 'The client writes a prediction before facing a small feared situation and the actual outcome afterward, with a 0 to 100 rating of how sure they were. Look at gaps together without pushing a conclusion; the pattern across entries is what is useful.', '[{"id": "f0", "type": "textarea", "label": "What I predicted:"}, {"id": "f1", "type": "textarea", "label": "What happened:"}, {"id": "f2", "type": "textarea", "label": "The gap:"}, {"id": "f3", "type": "textarea", "label": "What I learned:"}]'::jsonb, array['phobias', 'CBT', 'predictions', 'phobia']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('willingness-scale-for-approaching-fear', 'Willingness Scale for Approaching Fear', 'act'::resource_kind, 'A scale rating willingness before a step.', 'Use it to help a client choose steps they are willing to take.', array['Adults', 'Teens']::text[], '20 minutes', 'Rate willingness from 0 to 10 for a few possible steps and choose one near a 6, so it stretches without overwhelming. Link the step to a value. The clinician sets pacing and reviews afterward what the client noticed in the body and mind.', '[{"id": "f0", "type": "textarea", "label": "The step:"}, {"id": "f1", "type": "textarea", "label": "Willingness rating:"}, {"id": "f2", "type": "textarea", "label": "The value behind it:"}, {"id": "f3", "type": "textarea", "label": "What I noticed:"}]'::jsonb, array['phobias', 'ACT', 'willingness', 'phobia']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('fear-friend-drawing-series', 'Fear Friend Drawing Series', 'kids'::resource_kind, 'A child draws the feared thing becoming friendlier.', 'Use it to soften a child''s image of a fear.', array['Children']::text[], '25 minutes', 'Draw it scary, then silly, then friendly. The parent models calm. Follow your reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw the scary version."}, {"id": "f1", "type": "textarea", "label": "Draw a silly version."}, {"id": "f2", "type": "textarea", "label": "Draw a friendly version."}, {"id": "f3", "type": "textarea", "label": "Draw my brave step."}]'::jsonb, array['phobias', 'kids', 'fear', 'drawing']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('fear-fishing-game', 'Fear Fishing Game', 'game'::resource_kind, 'A game where players fish for small brave tasks.', 'Use it to make small approach steps playful.', array['Children', 'Teens', 'Groups']::text[], '25 minutes', 'Make paper fish with small brave tasks and a paperclip, and fish with a magnet. Rules: a player may pass once and tasks stay within what the clinician has approved. Debrief on how it felt to try and what surprised them.', '[{"id": "f0", "type": "textarea", "label": "The task I caught:"}, {"id": "f1", "type": "textarea", "label": "How it felt:"}, {"id": "f2", "type": "textarea", "label": "What surprised me:"}, {"id": "f3", "type": "textarea", "label": "Next step:"}]'::jsonb, array['phobias', 'game', 'brave tasks', 'groups']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('body-neutrality-daily-notes', 'Body Neutrality Daily Notes', 'worksheet'::resource_kind, 'Daily notes of neutral facts about the body.', 'Use it to build a neutral view of the body.', array['Adults', 'Teens']::text[], 'One week', 'The client writes one or two plain facts a day about what the body does, such as "my legs carried me," with nothing about looks. Review at the end of the week and ask how neutral facts felt compared with judgments.', '[{"id": "f0", "type": "textarea", "label": "A neutral fact today:"}, {"id": "f1", "type": "textarea", "label": "Another:"}, {"id": "f2", "type": "textarea", "label": "How it felt to write:"}, {"id": "f3", "type": "textarea", "label": "What I noticed:"}]'::jsonb, array['body image', 'worksheet', 'neutrality']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('media-messages-thought-check', 'Media Messages Thought Check', 'cbt'::resource_kind, 'A sheet for looking at messages from media about how people should look.', 'Use it to help a client question media messages.', array['Adults', 'Teens']::text[], '25 minutes', 'Have the client name a message from media about how people should look, who gains from it, and a fairer thought. Keep the talk on messages and thoughts, never on measuring or changing the body. Ask what the client wants to scroll past or follow instead.', '[{"id": "f0", "type": "textarea", "label": "The message I saw:"}, {"id": "f1", "type": "textarea", "label": "How it made me feel:"}, {"id": "f2", "type": "textarea", "label": "A fairer thought:"}, {"id": "f3", "type": "textarea", "label": "What I will do:"}]'::jsonb, array['CBT', 'media', 'body image']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('who-i-am-beyond-looks-compass', 'Who I Am Beyond Looks Compass', 'act'::resource_kind, 'A compass of qualities and values.', 'Use it to help a client anchor in values.', array['Adults', 'Teens']::text[], '25 minutes', 'Draw a compass and have the client write qualities they are proud of, the values behind them, and one step this week to live them. Keep appearance out of the page. Ask who in their life sees these qualities and how they know.', '[{"id": "f0", "type": "textarea", "label": "Qualities I am proud of:"}, {"id": "f1", "type": "textarea", "label": "Values behind them:"}, {"id": "f2", "type": "textarea", "label": "A step:"}, {"id": "f3", "type": "textarea", "label": "Who sees these in me:"}]'::jsonb, array['body image', 'ACT', 'values']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('body-kindness-collage', 'Body Kindness Collage', 'kids'::resource_kind, 'A child makes a collage of things the body can do.', 'Use it to build a kind view of the body.', array['Children', 'Teens']::text[], '30 minutes', 'Pictures of activity and care. The parent talks about what bodies do, not looks. Follow your reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw what my body can do."}, {"id": "f1", "type": "textarea", "label": "Draw something kind I do for it."}, {"id": "f2", "type": "textarea", "label": "Draw what I like."}, {"id": "f3", "type": "textarea", "label": "Draw who is kind."}]'::jsonb, array['body image', 'kids', 'kindness', 'collage']::text[], '2026-11-02T15:00:00+00:00'::timestamptz),
  ('appreciating-each-other-beyond-looks', 'Appreciating Each Other Beyond Looks', 'couples'::resource_kind, 'Partners name qualities they value in each other apart from appearance.', 'Use it to help partners value each other.', array['Couples']::text[], '20 minutes', 'Each partner writes five qualities they value in the other that have nothing to do with looks, then reads them aloud. Partner A and Partner B take turns receiving. Ask what it was like to hear it and how they might say more of it at home.', '[{"id": "f0", "type": "textarea", "label": "Partner A: qualities I value in my partner:"}, {"id": "f1", "type": "textarea", "label": "Partner B: qualities I value in my partner:"}, {"id": "f2", "type": "textarea", "label": "What it was like to hear it:"}, {"id": "f3", "type": "textarea", "label": "How we will say more:"}]'::jsonb, array['body image', 'couples', 'appreciation']::text[], '2026-11-02T15:00:00+00:00'::timestamptz)
